from orders.application.order_service import OrderNotFound, OrderService


@dataclass(frozen=True)
class Response:
    status: int
    body: dict[str, Any]


class OrderController:
    def __init__(self, service: OrderService) -> None:
        self._service = service

    def handle_gift_wrap(self, order_id: str, request: dict[str, Any]) -> Response:
        message = request.get("message")
        if not isinstance(message, str) or not 1 <= len(message) <= 200:
            return Response(400, {"error": "message must be 1 to 200 characters"})
        try:
            order = self._service.add_gift_wrap(order_id, message)
        except OrderNotFound:
            return Response(404, {"error": "order not found"})
        return Response(200, {"order_id": order.order_id, "gift_wrap": True})

