from orders.application.order_service import OrderNotFound, OrderService


@dataclass(frozen=True)
class Response:
    status: int
    body: dict[str, Any]


class OrderController:
    def __init__(self, service: OrderService) -> None:
        self._service = service

    def handle_apply_coupon(self, order_id: str, request: dict[str, Any]) -> Response:
        code = request.get("code")
        if not isinstance(code, str) or not code:
            return Response(400, {"error": "code must be a non-empty string"})
        try:
            summary = self._service.apply_coupon(order_id, code)
        except OrderNotFound:
            return Response(404, {"error": "order not found"})
        except ValueError as exc:
            return Response(422, {"error": str(exc)})
        return Response(200, {"order_id": order_id, "total_cents": summary.total_cents})

