class Response:
    status: int
    body: dict[str, Any]


class OrderController:
    def __init__(self, service: OrderService) -> None:
        self._service = service

    def handle_loyalty_price(self, order_id: str, customer_tier: str) -> Response:
        try:
            order = self._service.get_order(order_id)
        except OrderNotFound:
            return Response(404, {"error": "order not found"})
        subtotal = order.subtotal_cents
        discount = subtotal * 5 // 100 if customer_tier == "gold" else 0
        return Response(200, {"order_id": order_id, "discount_cents": discount,
                              "total_cents": subtotal - discount})

