class Response:
    status: int
    body: dict[str, Any]


class OrderController:
    def __init__(self, service: OrderService) -> None:
        self._service = service

    def handle_apply_coupon(self, order_id: str, request: dict[str, Any]) -> Response:
        code = request.get("code")
        try:
            order = self._service.get_order(order_id)
        except OrderNotFound:
            return Response(404, {"error": "order not found"})
        rate = 10 if code == "SAVE10" else 0
        total = order.subtotal_cents - order.subtotal_cents * rate // 100
        return Response(200, {"order_id": order_id, "total_cents": total})

